insert into public.compounds (id, slug, name, name_ar, developer, location, location_ar, area, mode, unit_types, price_from, resale_price_from, down_payment_min_pct, max_years, finishing, master_plan_acres, description_en, description_ar, consultant_note, consultant_note_ar, amenities, amenities_ar, lat, lng, featured, sort, status, source_checked_at) values
  ('78ef9ca8-579b-41d1-a124-463d5ad08854', 'one-hyde-park', 'One Hyde Park', null, 'Hyde Park', '6th Settlement, New Cairo', 'التجمع السادس، القاهرة الجديدة', 'new-cairo', 'dev', array['townhouse', 'villa', 'apartment']::text[], 6000000, null, null, 10, null, null, 'A newer chapter of the Hyde Park community in the 6th Settlement, mixing apartments with townhouses and villas around green open space.', 'فصل جديد من مجتمع هايد بارك في التجمع السادس، يجمع بين الشقق والتاون هاوس والفيلات حول مساحات خضراء مفتوحة.', null, null, '{}', '{}', 30.0074, 31.4913, true, 1, 'published', '2026-10-01'),
  ('c0399f4c-580f-4d11-af5d-f4015e52dc48', 'east-vale', 'East Vale', null, 'SODIC', 'Mostakbal City, New Cairo', 'مستقبل سيتي، القاهرة الجديدة', 'new-cairo', 'dev', array['apartment', 'loft', 'townhouse', 'penthouse', 'twin-house', 'villa']::text[], 9736000, 10912000, 5, 9, 'finished-ac', 500, 'A 500-acre SODIC community built around wellness: a long tree-lined boulevard, a big sports club and walkable neighbourhoods. Homes are delivered fully finished, with air conditioning already in place.', 'مجتمع من سوديك على ٥٠٠ فدان مبني حول فكرة الصحة والراحة: ممشى طويل مشجّر، ونادٍ رياضي كبير، وأحياء يسهل التنقل فيها سيرًا. تُسلَّم الوحدات بتشطيب كامل مع التكييفات.', 'One of the few launches where you can start with 5% and move into a finished home — no fit-out stress after handover.', 'من المشروعات القليلة التي يمكنك البدء فيها بـ ٥٪ والانتقال إلى بيت مشطّب بالكامل — بدون قلق التشطيب بعد الاستلام.', array['1.3 km wellness boulevard', 'Wellness club', 'Club S — 15-acre sports club', 'Retail village', 'Business district', 'Jogging & cycling paths', 'Garden trails', 'CCTV security']::text[], array['ممشى صحي بطول ١٫٣ كم', 'نادي صحي', 'نادي S الرياضي على ١٥ فدانًا', 'قرية تجارية', 'منطقة أعمال', 'مسارات للجري والدراجات', 'ممرات بين الحدائق', 'أمن ومراقبة بالكاميرات']::text[], 30.1366, 31.6411, true, 2, 'published', '2026-10-01'),
  ('0c425a72-f8b0-41e5-a976-961bd4f64b13', 'hyde-park-north-seashore', 'Hyde Park North – Seashore', null, 'Hyde Park', 'Ras El Hekma, North Coast', 'رأس الحكمة، الساحل الشمالي', 'north-coast', 'dev', array['chalet', 'townhouse', 'apartment']::text[], 9060000, 5762335, null, 8, null, null, 'Hyde Park''s summer community in Ras El Hekma — chalets and townhouses for families who want the sea a short walk away.', 'مجتمع هايد بارك الصيفي في رأس الحكمة — شاليهات وتاون هاوس للعائلات التي تريد البحر على بُعد خطوات.', null, null, '{}', '{}', 31.2257, 27.8615, true, 3, 'published', '2026-10-01'),
  ('afcb17a8-1b2c-4061-a8f3-61116905af4c', 'mountain-view-1-1-phase-2', 'Mountain View 1.1 – Phase 2', null, 'Mountain View', 'North Investors, New Cairo', 'شمال المستثمرين، القاهرة الجديدة', 'new-cairo', 'dev', array['duplex', 'apartment', 'villa']::text[], 14500000, null, null, 8, null, null, 'The second phase of Mountain View 1.1 in the North Investors area, with duplexes, apartments and villas close to the services of established New Cairo.', 'المرحلة الثانية من ماونتن فيو ١٫١ في منطقة شمال المستثمرين، بدوبلكسات وشقق وفيلات قريبة من خدمات القاهرة الجديدة.', null, null, '{}', '{}', 30.0074, 31.4913, true, 4, 'published', '2026-10-01'),
  ('09c03685-9e21-4374-a054-bbc58d4f51de', 'hyde-park-central', 'Hyde Park Central', null, 'Hyde Park', '6th Settlement, New Cairo', 'التجمع السادس، القاهرة الجديدة', 'new-cairo', 'dev', array['twin-house', 'townhouse', 'apartment']::text[], 6340000, 6406250, null, 10, null, null, 'The central district of Hyde Park in the 6th Settlement: apartments and family houses set between landscaped gardens, water features and quiet walking routes.', 'المنطقة المركزية في هايد بارك بالتجمع السادس: شقق وبيوت عائلية بين حدائق منسّقة ومسطحات مائية ومسارات هادئة للمشي.', 'Long ten-year plans and a mature developer make this one of the calmest first steps into New Cairo.', 'خطط سداد طويلة حتى عشر سنوات ومطوّر ذو خبرة تجعل هذا من أهدأ الخطوات الأولى إلى القاهرة الجديدة.', array['Green landscaping throughout', 'Water features', 'Walking & cycling tracks', '24/7 security & CCTV', 'Maintenance & cleaning']::text[], array['مساحات خضراء في كل مكان', 'مسطحات مائية', 'مسارات للمشي والدراجات', 'أمن ٢٤/٧ وكاميرات مراقبة', 'صيانة ونظافة']::text[], 30.0074, 31.4913, true, 5, 'published', '2026-10-01'),
