insert into public.units (id, slug, compound_id, project, sale_type, unit_type, beds, baths, size_m2, garden_m2, terrace_m2, land_m2, price, price_max, down_payment_amount, down_payment_pct, installment_amount, installment_frequency, installment_years, delivery, finishing, floor, cash_only, consultant_note, consultant_note_ar, featured, status, listing_status, sort) values
  ('2cccf7a7-50bd-428e-a84e-62c5c1928f36', 'central-residence-2-bed-apartment', '09c03685-9e21-4374-a054-bbc58d4f51de', 'Central Residence', 'offplan', 'apartment', 2, 3, 101, null, 5, null, 9500000, 10230000, 475000, 5, 213750, 'quarterly', 10, '2030-01', 'not-finished', null, false, 'It''s one of the gentlest ways into Hyde Park: just 5% to reserve, then small quarterly payments over ten years — ideal for a young couple or a first investment. You get a third bathroom and a little terrace for morning coffee, and because it''s delivered unfinished in 2030, you''ll design the inside exactly the way you like.', 'من أسهل الطرق لدخول هايد بارك: ٥٪ فقط للحجز، ثم أقساط ربع سنوية صغيرة على عشر سنوات — مثالية لزوجين في بداية حياتهما أو كأول استثمار. ستحصل على حمّام ثالث وتراس صغير لقهوة الصباح، ولأنها تُسلَّم بدون تشطيب في ٢٠٣٠ ستصمّم الداخل تمامًا كما تحب.', true, 'available', 'published', 1),
  ('be920d72-1ce3-4c5f-af3e-98cd73b669d8', 'waterway-north-coast-3-bed-chalet', '950382fb-a657-4214-a240-af2d907aade7', null, 'offplan', 'chalet', 3, 4, 185, null, null, null, 35136000, 39072000, 3513600, 10, 1129371, 'quarterly', 7, '2027-09', 'finished', null, false, 'A finished three-bedroom chalet that will be ready for the summer of 2028 — with a bathroom for every bedroom, so the whole family and their guests are comfortable.', 'شاليه بثلاث غرف نوم مشطّب بالكامل سيكون جاهزًا لصيف ٢٠٢٨ — مع حمّام لكل غرفة، ليرتاح الجميع، العائلة والضيوف.', true, 'available', 'published', 2),
  ('bef70478-fa30-4bbf-a28c-122b2931ec9d', 'patio-vida-3-bed-apartment', '890b84c8-e1a5-4a67-aa55-4cb72547867d', null, 'offplan', 'apartment', 3, 3, 214, null, null, null, 12300000, null, null, null, null, null, null, '2029', null, null, false, '214 m² for three bedrooms is a lot of living space for the price — room for a study or a playroom without moving up to a villa budget.', '٢١٤ م² لثلاث غرف نوم مساحة كبيرة مقابل السعر — مكان لغرفة مكتب أو ألعاب دون الوصول لميزانية فيلا.', true, 'available', 'published', 3),
  ('e1d573fc-807e-45fb-a293-085bcdd730a5', 'patio-vida-4-bed-penthouse', '890b84c8-e1a5-4a67-aa55-4cb72547867d', null, 'offplan', 'penthouse', 4, 4, 214, null, null, null, 14700000, null, null, null, null, null, null, '2029', null, null, false, 'A penthouse with four bedrooms on the top floor — more light and more privacy, for a little more than the apartment below it.', 'بنتهاوس بأربع غرف نوم في الدور الأخير — ضوء أكثر وخصوصية أكبر، بفارق بسيط عن الشقة التي تحته.', false, 'available', 'published', 4),
  ('406e56c9-85c1-4536-a618-ae75424fe413', 'noll-2-bed-apartment-121', '99e73961-ac4c-4dea-a1be-4505d7f93d67', null, 'offplan', 'apartment', 2, 3, 121, null, null, null, 8072560, null, null, null, null, null, null, '2029', null, null, false, 'One of the lowest entry prices I have in the 6th Settlement, and the extra bathroom makes it feel bigger than its 121 m².', 'من أقل أسعار الدخول التي لديّ في التجمع السادس، والحمّام الإضافي يجعلها تبدو أكبر من مساحتها ١٢١ م².', true, 'available', 'published', 5),
  ('446e5d15-9d70-4f12-ad92-9ea58a15c41b', 'noll-2-bed-apartment-125', '99e73961-ac4c-4dea-a1be-4505d7f93d67', null, 'offplan', 'apartment', 2, 2, 125, null, null, null, 8300000, null, null, null, null, null, null, '2029', null, null, false, 'A slightly larger two-bedroom in the same community — worth comparing side by side with the 121 m² layout.', 'شقة بغرفتين أكبر قليلًا في نفس المجتمع — تستحق المقارنة جنبًا إلى جنب مع تصميم الـ ١٢١ م².', false, 'available', 'published', 6),
  ('06bfb3fb-8618-4022-ab98-00fd744b892a', 'el-patio-riva-2-bed-apartment', '29e8a8ca-a686-41a3-aa2a-8d19e74616d4', null, 'offplan', 'apartment', 2, 2, 125, null, null, null, 8700000, null, null, null, null, null, null, '2030', null, null, false, 'A later 2030 delivery gives you more time to pay — a good fit if you want smaller instalments now.', 'التسليم في ٢٠٣٠ يمنحك وقتًا أطول للسداد — مناسبة إذا كنت تفضّل أقساطًا أصغر الآن.', false, 'available', 'published', 7),
  ('f729d57a-9cce-4ec5-a4c4-37338c3ec7b5', 'ever-new-cairo-3-bed-townhouse', '0605c630-d202-459b-ac19-37f7a4610a99', null, 'offplan', 'townhouse', 3, 3, 210, null, null, null, 22270000, null, null, null, null, null, null, '2028', null, null, false, 'Your own front door and a house on several levels, delivered in 2028 — a real step up from apartment living.', 'باب خاص وبيت على أكثر من مستوى، يُسلَّم في ٢٠٢٨ — خطوة حقيقية بعد السكن في شقة.', true, 'available', 'published', 8),
  ('ce05232b-0f3c-4d9a-a65f-05c5f80736d6', 'crescent-walk-3-bed-apartment', '01315f59-4b0a-4f38-aa1a-d5e5d7de1ec2', null, 'offplan', 'apartment', 3, 6, 213, null, null, null, 22900000, null, null, null, null, null, null, '2030', null, null, false, 'Six bathrooms in a 213 m² apartment means en-suites everywhere plus guest and staff bathrooms — rare outside a villa.', 'ستة حمّامات في شقة ٢١٣ م² تعني حمّامًا خاصًا لكل غرفة بالإضافة لحمّام للضيوف وآخر للخدمة — أمر نادر خارج الفيلات.', false, 'available', 'published', 9),
  ('c31750d8-d5f1-4a6f-ad2b-7c7f20089783', 'new-giza-1-bed-apartment', 'd538899a-e57f-4d71-aa6c-3d27ed1a577b', null, 'offplan', 'apartment', 1, 1, 105, null, null, null, 10500000, null, null, null, null, null, 3.3, 'near', null, null, false, 'Close to delivery in an already-lived-in community — you pay over about three years and move in soon, not in 2030.', 'قريبة من التسليم في مجتمع يسكنه الناس بالفعل — تدفع على حوالي ثلاث سنوات وتنتقل قريبًا، وليس في ٢٠٣٠.', true, 'available', 'published', 10),
  ('fd6a5b11-6702-4426-a0ec-25454e0437fb', 'garden-lakes-2-bed-apartment', '28b7709a-2b89-42f9-af0e-5acfa32becef', null, 'offplan', 'apartment', 2, 2, 113, null, null, null, 11640000, null, null, null, null, null, null, 'near', null, null, false, 'Near delivery with lake views around the community — a calm place to settle on the west side.', 'قريبة من التسليم مع إطلالات على البحيرات حول المجتمع — مكان هادئ للاستقرار في غرب القاهرة.', false, 'available', 'published', 11),
  ('75a49a04-8317-4755-aeaf-9d81d43022a8', 'capitalway-4-bed-garden-apartment', '09d14ebb-d9b9-4024-a50b-b3a95e1d5919', null, 'ready', 'apartment', 4, 3, 180, 120, null, null, 13000000, null, null, null, null, null, null, 'ready', 'finished', 'Ground floor', true, 'Ready, fully finished and on the ground floor with a 120 m² garden — a family can move in this season without touching a paintbrush.', 'جاهزة ومشطّبة بالكامل في الدور الأرضي مع حديقة ١٢٠ م² — تستطيع العائلة الانتقال هذا الموسم دون أي تشطيب.', true, 'available', 'published', 12),
  ('56cbbd4c-d79e-4905-aea8-1431c4f1fbc6', 'new-giza-kingsrange-1-bed-apartment', 'd538899a-e57f-4d71-aa6c-3d27ed1a577b', 'Kingsrange', 'ready', 'apartment', 1, 2, 100, null, null, null, 12000000, null, null, null, null, null, null, 'ready', 'finished', null, true, 'A finished one-bedroom in the delivered Kingsrange phase — easy to live in or to rent out straight away.', 'شقة بغرفة واحدة مشطّبة في مرحلة كينجز رينج المسلّمة — سهلة للسكن أو للإيجار فورًا.', false, 'available', 'published', 13),
  ('f3a73054-54ba-4049-aa5f-dc2966a73a1e', 'zed-2-bed-apartment', '204e0d39-624c-4d54-afa7-908df09a2d54', null, 'ready', 'apartment', 2, 2, 129, null, null, null, 13289500, null, null, null, null, null, null, 'ready', null, null, false, 'Ready to live in, in Sheikh Zayed — a good choice if work or school keeps you on the west side.', 'جاهزة للسكن في الشيخ زايد — اختيار جيد إذا كان عملك أو مدرسة أولادك في غرب القاهرة.', false, 'available', 'published', 14),
  ('63f0b0a0-4bc4-4f37-a05b-6ddfb968dd95', 'px-1-bed-apartment', '1572009a-0b4c-4b59-a7cc-b3cf93da7511', null, 'ready', 'apartment', 1, 1, 78, null, null, null, 13361793, null, null, null, null, null, 7, 'ready', null, null, false, 'Rare to find a ready home that still comes with a seven-year plan — you move in now and keep paying gradually.', 'من النادر أن تجد بيتًا جاهزًا ما زال بخطة سداد على سبع سنوات — تنتقل الآن وتستمر في السداد تدريجيًا.', false, 'available', 'published', 15),
  ('0c8c129b-d7cc-4a74-a8ae-61d51cf1e8c9', 'azzar-5-bed-twin-house', '6dfbcdec-2f43-4285-afce-235d3412f4ee', null, 'ready', 'twin-house', 5, 4, 305, null, null, null, 45000000, null, null, null, null, null, null, 'ready', null, null, false, 'Five bedrooms, ready now — space for grandparents to stay without anyone giving up their room.', 'خمس غرف نوم وجاهزة الآن — مساحة ليقيم الأجداد دون أن يتنازل أحد عن غرفته.', false, 'available', 'published', 16),
  ('78b36e25-f2c8-4b60-a774-748570bc2b08', 'pk2-5-bed-villa', '993664f9-477a-46f0-a5c6-f8cd608b8f3a', null, 'ready', 'villa', 5, 6, 520, null, null, null, 55000000, null, null, null, null, null, null, 'ready', null, null, false, 'A big family villa in a community where the trees have had years to grow — it already feels like a neighbourhood.', 'فيلا عائلية كبيرة في مجتمع كبرت أشجاره عبر السنين — يبدو بالفعل كحي متكامل.', false, 'available', 'published', 17),
  ('23270f41-f97b-4a66-a5f0-304d99a9c063', 'villette-5-bed-villa-362', '90206211-9c8b-40ea-a129-2f2d68f1e93f', null, 'ready', 'villa', 5, 5, 362, null, null, null, 58000000, null, null, null, null, null, null, 'ready', null, null, false, 'A ready SODIC villa in the Golden Square — schools, malls and the ring road are all minutes away.', 'فيلا جاهزة من سوديك في الجولدن سكوير — المدارس والمولات والطريق الدائري على بُعد دقائق.', true, 'available', 'published', 18),
  ('6f0106af-a008-4db6-acd1-88255c270ea8', 'pk1-4-bed-villa', 'bc6f5d51-ce29-4498-aef1-284564efc8b4', null, 'ready', 'villa', 4, 6, 550, null, null, null, 67000000, null, null, null, null, null, null, 'ready', null, null, false, 'Fewer bedrooms but 550 m² of living space — for a family that wants big rooms rather than many of them.', 'غرف أقل لكن ٥٥٠ م² من المساحة — لعائلة تفضّل الغرف الواسعة على كثرة الغرف.', false, 'available', 'published', 19),
  ('21270c1b-eda3-4578-a851-2fa14d5eeb93', 'villette-5-bed-villa-360', '90206211-9c8b-40ea-a129-2f2d68f1e93f', null, 'ready', 'villa', 5, 5, 360, null, null, 600, 78000000, null, null, null, null, null, null, 'ready', 'semi-finished', null, true, 'Delivered and semi-finished on a 600 m² plot — you choose every finish yourself, with a large garden to plan around.', 'مسلّمة ونصف تشطيب على أرض ٦٠٠ م² — تختار كل تفاصيل التشطيب بنفسك، مع حديقة كبيرة تخطط لها.', false, 'available', 'published', 20);
