insert into public.story_items (id, year, title, title_ar, text, text_ar, sort) values
  ('18a456c1-1505-4e28-ac2e-9fb5209d041a', '2019', 'Where it began', 'البداية', 'My first sale: a young couple''s two-bedroom in New Cairo. Seeing their faces at handover is why I stayed.', 'أول بيعة لي: شقة بغرفتين لزوجين شابين في القاهرة الجديدة. رؤية وجوههما يوم الاستلام هي سبب بقائي في هذا العمل.', 1),
  ('28a2315a-3e37-468b-a51e-2c799b821358', '2021', 'New launches & payment plans', 'المشروعات الجديدة وخطط السداد', 'Began advising on off-plan launches in New Cairo and the New Capital — and explaining long instalment plans in plain words.', 'بدأت أقدّم المشورة في مشروعات الإطلاق الجديدة في القاهرة الجديدة والعاصمة الإدارية — وأشرح خطط التقسيط الطويلة بكلمات بسيطة.', 2),
  ('26a22e34-4a0f-4b79-aad5-672d485e7eec', '2023', 'Homes by the sea', 'بيوت على البحر', 'Added North Coast summer homes in Ras El Hekma and Al Dabaa for families who wanted a second home.', 'أضفت بيوت الساحل الشمالي الصيفية في رأس الحكمة والضبعة للعائلات التي تريد بيتًا ثانيًا.', 3),
  ('779c23b6-6399-44d9-a303-201b291a0cc1', 'Today', 'Your consultant, one-to-one', 'مستشارك، وجهًا لوجه', 'Advising families across New Cairo, the New Capital, 6th of October, Sheikh Zayed and the North Coast.', 'أقدّم المشورة للعائلات في القاهرة الجديدة والعاصمة الإدارية و٦ أكتوبر والشيخ زايد والساحل الشمالي.', 4);
insert into public.settings (id, consultant_name, consultant_name_ar, title, title_ar, portrait_path, avatar_path, phone, whatsapp, email, hours, hours_ar, open_days, open_from, open_to, available, areas, areas_ar, social, story_intro, story_intro_ar, quote, quote_ar) values
  (1, 'Romany', 'روماني', 'Your property consultant in Cairo', 'مستشارك العقاري في القاهرة', '/romany-portrait.jpg', '/romany-avatar.jpg', '201000000000', '201000000000', null, 'Saturday – Thursday · 11 am – 9 pm', 'السبت – الخميس · ١١ صباحًا – ٩ مساءً', '{6,0,1,2,3,4}', 11, 21, true, array['New Cairo', 'New Capital', '6th of October', 'North Coast']::text[], array['القاهرة الجديدة', 'العاصمة الإدارية', '٦ أكتوبر', 'الساحل الشمالي']::text[], '{}'::jsonb, 'I grew up in Cairo watching my parents save for years for their first apartment — and worry over every line of the contract. Today I help families make that same step with clear numbers and far less stress. I only show homes I''d recommend to my own family, and I''m still a phone call away long after the keys are handed over.', 'كبرت في القاهرة وأنا أرى والديّ يدّخران لسنوات من أجل أول شقة لهما — ويقلقان من كل سطر في العقد. اليوم أساعد العائلات على اتخاذ نفس الخطوة بأرقام واضحة وقلق أقل بكثير. لا أعرض إلا بيوتًا أنصح بها عائلتي، وأظل على بُعد مكالمة حتى بعد تسليم المفاتيح بوقت طويل.', 'I don''t sell units. I help families choose where their next ten years happen — and I tell them honestly when a place isn''t right.', 'أنا لا أبيع وحدات. أنا أساعد العائلات على اختيار المكان الذي ستعيش فيه سنواتها العشر القادمة — وأقول لهم بصراحة عندما لا يكون المكان مناسبًا.');
